import SelectInputForm from '@/components/forms/SelectInputForm';
import TextInputForm from '@/components/forms/TextInputForm';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { MaintenanceOrder } from '@/types/maintenance';
import { Department } from '@/types/department.types';
import { useEffect, useState } from 'react';

interface Props {
    maintenanceOrder?: MaintenanceOrder | null;
}

export default function ComplaintInfo({ maintenanceOrder }: Props) {
    const [departmentOptions, setDepartmentOptions] = useState<{ name: string; value: string }[]>([]);
    const [departmentsError, setDepartmentsError] = useState<string | null>(null);

    useEffect(() => {
        const fetchDepartments = async () => {
            try {
                const response = await apiGet({
                    endpoint: endpoints.departments.list,
                    queryParams: { page: 1, pageSize: 500, status: 'all' },
                });
                const rows: Department[] = response.data?.data?.data ?? [];
                const list = Array.isArray(rows) ? rows : [];
                const options = list
                    .filter((d) => d.is_active !== false)
                    .map((d) => ({ name: d.name, value: String(d.id) }));
                setDepartmentOptions(options);
                setDepartmentsError(null);
            } catch {
                setDepartmentOptions([]);
                setDepartmentsError('تعذر تحميل الأقسام.');
            }
        };
        fetchDepartments();
    }, []);

    return (
        <div className="my-6">
            {departmentsError && (
                <p className="mb-4 text-sm text-amber-800 bg-amber-50 border border-amber-200 rounded px-3 py-2">{departmentsError}</p>
            )}
            <div className="grid grid-cols-1 gap-6">
                <TextInputForm name="title" placeholder="بحث عن منتج، أو كتابة عنوان الشكوى" label="موضوع الشكوى" />
                <SelectInputForm
                    name="type"
                    placeholder="خيارات"
                    label="طريقة استقبال الشكوى"
                    options={[
                        { name: 'البريد الإلكتروني', value: 'email' },
                        { name: 'الهاتف', value: 'phone' },
                        { name: 'الفاكس', value: 'fax' },
                        { name: 'البريد العادي', value: 'mail' },
                    ]}
                    data={maintenanceOrder}
                />
                <SelectInputForm
                    name="department"
                    placeholder={departmentOptions.length ? 'اختر القسم' : 'جاري التحميل...'}
                    label="القسم المختص"
                    options={departmentOptions}
                    data={maintenanceOrder}
                />
            </div>
        </div>
    );
}
